<?php
declare(strict_types=1);
require_once __DIR__ . '/_seller.php';
$pdo = market_boot(); $user = market_require_user($pdo); seller_access_or_message($pdo, $user);
$ctx = seller_query_context($pdo, $user, true); $seller = $ctx['seller']; seller_header('Orders', 'orders', $user, $seller);
if ($ctx['message']): ?><div class="alert ok"><?= e($ctx['message']) ?></div><?php endif; if ($ctx['error']): ?><div class="alert err"><?= e($ctx['error']) ?></div><?php endif; ?>
<section class="sc-grid"><?php foreach ($ctx['orders'] as $row): ?><form method="post" class="sc-card sc-panel span-6 sc-form"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_order"><input type="hidden" name="order_id" value="<?= (int) $row['id'] ?>"><div class="sc-panel-head"><h2><?= e((string) $row['order_ref']) ?></h2><span class="badge blue"><?= e(marketplace_money((float) $row['total_amount'])) ?></span></div><p><strong><?= e((string) $row['listing_title']) ?></strong><br><span class="muted"><?= e((string) $row['buyer_name']) ?> / Qty <?= e((string) $row['quantity']) ?></span></p><div class="sc-form-grid"><select name="status"><?php foreach (['quoted','accepted','preparing','ready','scheduled','in_transit','completed','cancelled','disputed'] as $status): ?><option value="<?= e($status) ?>" <?= (string) $row['status'] === $status ? 'selected' : '' ?>><?= e(marketplace_status_label($status)) ?></option><?php endforeach; ?></select><select name="delivery_status"><?php foreach (['not_started','awaiting_seller','packing','ready_for_pickup','scheduled','in_transit','delivered','failed','returned'] as $status): ?><option value="<?= e($status) ?>" <?= (string) ($row['delivery_status'] ?? 'awaiting_seller') === $status ? 'selected' : '' ?>><?= e(marketplace_status_label($status)) ?></option><?php endforeach; ?></select></div><textarea name="fulfillment_note"><?= e((string) ($row['fulfillment_note'] ?? '')) ?></textarea><button class="sc-btn" type="submit">Update Order</button></form><?php endforeach; ?><?php if (!$ctx['orders']): ?><div class="empty span-12">No order created yet.</div><?php endif; ?></section>
<?php seller_footer(); ?>
